INSERT INTO events (title,slug,description,event_type,status,start_date,end_date,registration_fee,is_free,banner_image,organizer) VALUES ('Advanced Implantology Hands-On Workshop','ev-002','Live cadaveric and model-based hands-on training in implant placement, sinus lift, and bone grafting. Faculty-led by top oral surgeons.','training','published','2026-12-01 10:00:00','2026-12-01 18:00:00',9999,0,'https://merchant-cdn.storedum.com/ai_img_22_(1).png','Smart Dental Innovations');
INSERT INTO events (title,slug,description,event_type,status,start_date,end_date,registration_fee,is_free,banner_image,organizer) VALUES ('RCT Endodontic Excellence Live Course','ev-003','Step-by-step rotary endodontic protocols, apex location, irrigation, and obturation. Real case demos with troubleshooting tips.','training','published','2026-12-01 10:00:00','2026-12-01 18:00:00',4999,0,'https://merchant-cdn.storedum.com/plain_image_2_53_(1).png','Smart Dental Innovations');
INSERT INTO testimonials (slug,name,avatar,product_image,text,sort_order) VALUES ('t-1','Aaradhya Dubey','https://i.pravatar.cc/100?img=47','https://picsum.photos/seed/review-1/300/300','I recently used this implant hex driver and was impressed by its quality. It felt sturdy in hand, the grip was precise, and torque transfer was smooth. Highly recommended for daily implant cases.',0);
INSERT INTO testimonials (slug,name,avatar,product_image,text,sort_order) VALUES ('t-2','Dr. Rohan Mehta','https://i.pravatar.cc/100?img=12','https://picsum.photos/seed/review-2/300/300','The endomotor is a game changer. Apex locator readings are stable and the torque control is reliable. My RCT chair time has dropped noticeably since I switched.',1);
INSERT INTO testimonials (slug,name,avatar,product_image,text,sort_order) VALUES ('t-3','Dr. Priya Sharma','https://i.pravatar.cc/100?img=32','https://picsum.photos/seed/review-3/300/300','Ordered the RF Cautery for soft tissue work. Cuts cleanly, minimal bleeding, patients report quick healing. Build quality on the handle feels premium.',2);
INSERT INTO testimonials (slug,name,avatar,product_image,text,sort_order) VALUES ('t-4','Dr. Kabir Singh','https://i.pravatar.cc/100?img=15','https://picsum.photos/seed/review-4/300/300','Fast shipping, fair pricing, and the after-sales response was on point. Will keep restocking accessories from here for my new clinic setup.',3);
