INSERT INTO site_settings (skey,svalue) VALUES ('policies','{\"return\":{\"title\":\"Return Policy\",\"sections\":[{\"h\":\"Eligibility\",\"p\":\"Most unused products may be returned within 7 days of delivery if sealed and in original packaging. Hygiene-sensitive items (intraoral burs, files, scrubs) are non-returnable once opened.\"},{\"h\":\"Process\",\"p\":\"Raise a return from Account → Orders → select item → Request Return. Our team will schedule pickup within 48 hours.\"},{\"h\":\"Refund Timeline\",\"p\":\"Refunds initiate within 3 business days of pickup quality-check. UPI/Card refunds reach your account in 5–7 business days. COD orders refund to original UPI/Bank shared at pickup.\"},{\"h\":\"Damaged or Incorrect Items\",\"p\":\"Report within 48 hours of delivery with unboxing video. Full refund or replacement at our cost.\"}]},\"terms\":{\"title\":\"Terms of Use\",\"sections\":[{\"h\":\"Acceptance\",\"p\":\"By accessing this site you agree to these terms. Products are sold business-to-business to licensed dental professionals and registered clinics.\"},{\"h\":\"Product Information\",\"p\":\"We attempt to display accurate product details, but specifications, packaging, and availability may change without notice. Always verify catalogue with our team before bulk orders.\"},{\"h\":\"Orders & Pricing\",\"p\":\"Prices are in INR and exclusive of statutory taxes unless stated. We reserve the right to cancel orders with incorrect price/stock, with full refund.\"},{\"h\":\"Liability\",\"p\":\"Smart Dental Innovations is not liable for clinical outcomes resulting from product use. Operators must follow manufacturer instructions and applicable regulations.\"},{\"h\":\"Governing Law\",\"p\":\"Disputes are subject to courts of Surat, Gujarat.\"}]},\"privacy\":{\"title\":\"Privacy Policy\",\"sections\":[{\"h\":\"Data We Collect\",\"p\":\"Name, phone, email, billing & shipping address, clinic GSTIN (if provided), order history, device/browser metadata, and pincode entered for delivery checks.\"},{\"h\":\"How We Use It\",\"p\":\"Fulfilling orders, payment processing, delivery, customer support, fraud prevention, statutory invoicing, and product communication you\'ve opted into.\"},{\"h\":\"Sharing\",\"p\":\"Limited sharing with logistics, payment gateways, and tax authorities as required. We never sell personal data.\"},{\"h\":\"Your Rights\",\"p\":\"Email us to access, correct, or delete your data. We retain order records as required by Indian tax law (typically 7 years).\"},{\"h\":\"Cookies\",\"p\":\"We use functional cookies for cart, login, and analytics. You may disable cookies, but parts of the site may not work.\"}]}}') ON DUPLICATE KEY UPDATE svalue=VALUES(svalue);
